10	import { subscribe } from "@/lib/event-bus";
11	import {
12	  drain,
13	  enqueue,
14	  isSchedulerRunning,
15	  pendingCount,
16	  resetQueue,
17	  startScheduler,
18	  stopScheduler,
19	} from "@/server/jobs";
20	import { backoffMs } from "@/server/jobs/webhook-delivery-job";
21	import { shouldRunForOrg } from "@/server/jobs/digest-email-job";
22	import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
23	import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
24	import * as issueRepo from "@/server/repositories/issue-repository";
25	import * as usageRepo from "@/server/repositories/usage-repository";
26	import * as issueService from "@/server/services/issue-service";
27	import { toIsoTimestamp } from "@/types/common";
28	import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
29	import type { Tenant } from "./_support/fixtures";
30	import type { Unsubscribe } from "@/types/event";
31	
32	let cleanup: () => void;
33	let tenant: Tenant;
34	const detachers: Unsubscribe[] = [];
35	
36	const PAST = "2026-01-01T00:00:00.000Z";
37	const NOW = new Date("2026-06-01T07:00:00.000Z");
38	
39	beforeAll(async () => {
40	  cleanup = await useTemporaryDatabase();
41	  tenant = await createTenant("jobs");
42	  await usageRepo.recomputeUsage(tenant.org.id);
43	});
44	
45	afterEach(() => {
46	  while (detachers.length > 0) detachers.pop()?.();
47	  resetQueue();
48	  stopScheduler();
49	});
50	
51	afterAll(() => {
52	  cleanup();
53	});
54	
55	describe("the in-process queue", () => {
56	  it("is idempotent on the job id", () => {
57	    const job = {
58	      id: "usage-rollup:1",
59	      kind: "usage-rollup" as const,
60	      runAt: toIsoTimestamp(NOW),
61	      attempts: 0,
62	      payload: {},
63	    };
64	
65	    enqueue(job);
66	    enqueue(job);
67	
68	    expect(pendingCount()).toBe(1);
69	  });
70	
71	  it("leaves jobs scheduled in the future alone", async () => {
72	    enqueue({
73	      id: "usage-rollup:future",
74	      kind: "usage-rollup",
75	      runAt: toIsoTimestamp(new Date(Date.now() + 3_600_000)),
76	      attempts: 0,
77	      payload: {},
78	    });
79	
80	    await expect(drain()).resolves.toBe(0);
81	    expect(pendingCount()).toBe(1);
82	  });
83	
84	  it("runs a due job and removes it", async () => {
85	    enqueue({
86	      id: "usage-rollup:due",
87	      kind: "usage-rollup",
88	      runAt: toIsoTimestamp(new Date(Date.now() - 1_000)),
89	      attempts: 0,
90	      payload: {},
91	    });
92	
93	    await expect(drain()).resolves.toBe(1);
94	    expect(pendingCount()).toBe(0);
95	  });
96	});
97	
98	describe("the scheduler", () => {
99	  it("reports whether it is running and stops cleanly", () => {
100	    expect(isSchedulerRunning()).toBe(false);
101	    startScheduler();
102	    expect(isSchedulerRunning()).toBe(true);
103	    stopScheduler();
104	    expect(isSchedulerRunning()).toBe(false);
105	  });
106	});
107	
108	describe("the overdue scan", () => {
109	  it("emits issue.overdue for a past-due open issue, once", async () => {
110	    const issue = await issueService.createIssue(
111	      tenant.actors.member,
112	      issueInput(tenant.org.id, tenant.project.id, {
113	        title: "Late already",
114	        assigneeId: tenant.userIds.member,
115	        dueAt: PAST,
116	      }),
117	    );
118	
119	    const seen: string[] = [];
120	    detachers.push(
121	      subscribe("issue.overdue", (payload) => {
122	        seen.push(payload.issueId);
123	      }),
124	    );
125	
126	    const result = await runOverdueIssueJob(NOW);
127	
128	    expect(seen).toEqual([issue.id]);
129	    expect(result.kind).toBe("overdue-issues");
130	    expect(result.processed).toBe(1);
131	    expect(result.failed).toBe(0);
132	  });
133	
134	  it("ignores an overdue issue once it is archived", async () => {
135	    const issue = await issueService.createIssue(
136	      tenant.actors.member,
137	      issueInput(tenant.org.id, tenant.project.id, {
138	        title: "Late but archived",
139	        dueAt: PAST,
140	      }),
141	    );
142	    await issueService.archiveIssue(
143	      tenant.actors.member,
144	      tenant.org.id,
145	      issue.id,
146	    );
147	
148	    const overdue = await issueRepo.listOverdueIssues(
149	      tenant.org.id,
150	      toIsoTimestamp(NOW),
151	    );
152	
153	    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
154	  });
155	
156	  it("ignores an overdue issue once it is closed", async () => {
157	    const issue = await issueService.createIssue(
158	      tenant.actors.member,
159	      issueInput(tenant.org.id, tenant.project.id, {
160	        title: "Late but done",
161	        dueAt: PAST,
162	      }),
163	    );
164	    await issueService.changeIssueStatus(tenant.actors.member, {
165	      orgId: tenant.org.id,
166	      issueId: issue.id,
167	      status: "done",
168	    });
169	
170	    const overdue = await issueRepo.listOverdueIssues(
171	      tenant.org.id,
172	      toIsoTimestamp(NOW),
173	    );
174	
175	    expect(overdue.map((row) => row.id)).not.toContain(issue.id);
176	  });
177	});
178	
179	describe("the usage rollup", () => {
180	  it("recounts the tenant's live rows", async () => {
181	    const result = await runUsageRollupJob(NOW);
182	    expect(result.processed).toBeGreaterThan(0);
183	
184	    const usage = await usageRepo.getUsage(tenant.org.id);
185	    const live = await issueRepo.listIssues({
186	      orgId: tenant.org.id,
187	      limit: 100,
188	      cursor: null,
189	    });
190	
191	    expect(usage.issuesUsed).toBe(live.total);
192	    expect(usage.seatsUsed).toBe(4);
193	  });
194	});
195	
196	describe("pure job helpers", () => {
197	  it("backs delivery attempts off exponentially, with a ceiling", () => {
198	    expect(backoffMs(0)).toBe(0);
199	    expect(backoffMs(1)).toBe(1_000);
200	    expect(backoffMs(2)).toBe(2_000);
201	    expect(backoffMs(3)).toBe(4_000);
202	    expect(backoffMs(30)).toBe(300_000);
203	  });
204	
205	  it("runs the digest only during the org's configured UTC hour", () => {
206	    const org = {
207	      ...tenant.org,
208	      settings: { ...tenant.org.settings, digestHourUtc: 7 },
209	    };
210	
211	    expect(shouldRunForOrg(org, NOW)).toBe(true);
212	    expect(
213	      shouldRunForOrg(org, new Date("2026-06-01T08:00:00.000Z")),
214	    ).toBe(false);
215	    expect(
216	      shouldRunForOrg({ ...org, archivedAt: toIsoTimestamp(NOW) }, NOW),
217	    ).toBe(false);
218	  });
219	});
